text:
#unifiedToolbar {
  flex: 1 1 auto;
  display: flex;
  align-items: center;
  padding-block: var(--unified-toolbar-padding);
  min-inline-size: 0;
  overflow: hidden;

  & .button:is(.toolbar-button, .unified-toolbar-button) {
    margin-block: 0;
  }
}

#unifiedToolbarContent {
  flex: 1 1 auto;
  min-block-size: max(var(--unified-toolbar-minimal-height), var(--unified-toolbar-searchbar-height), var(--unified-toolbar-content-min-height));
  margin: 0;
  /* Padding needed for the children's focus ring. */
  padding-block: 3px;
  padding-inline: var(--unified-drag-space) 3px;

  & li {
    -moz-window-dragging: no-drag;
  }

  & .unified-toolbar-button[disabled] {
    opacity: 0.4;
  }
